<?php

/**
 * @file
 * Prepares the API docs generated by phpdocumentor-markdown for MkDocs.
 *
 * The template writes each class to classes/<namespace path>.md, and links
 * for GitLab wikis, without ".md", which MkDocs neither rewrites nor checks.
 * This renames Home.md to index.md, gives each page a heading, moves the
 * module's classes to the top (\Drupal\<module>\Plugin is documented in
 * api/Plugin) and its test classes to api/Tests, and rewrites links to the
 * moved pages with ".md". Links to classes that weren't generated, such as
 * core's, become plain text. If the module has them, it also puts the hooks
 * from *.api.php files on one hooks.md page, and the event names, the
 * constants of classes named Events or *Events, on one events.md page. Both
 * are written next to the API pages' directory (docs/hooks.md for docs/api),
 * so the docs site lists them at the top level.
 *
 * Run it from the project's root, which has the module's *.info.yml file, or
 * pass the module's machine name.
 *
 * Usage: php fix-api-docs.php docs/api [module]
 */

declare(strict_types=1);

$dir = rtrim($argv[1] ?? '', '/');
if (!is_file("$dir/Home.md")) {
  fwrite(STDERR, "Usage: php fix-api-docs.php <directory with Home.md> [module]\n");
  exit(1);
}
$module = $argv[2] ?? basename(glob('*.info.yml')[0] ?? '', '.info.yml');
// New paths are relative to the docs directory, so hooks.md and events.md are
// top-level pages, next to the API pages' directory.
$root = dirname($dir);
$api = basename($dir);

// Where each namespace's pages are moved, by their generated path prefix.
$moves = ['Home.md' => "$api/index.md"];
if ($module !== '') {
  $moves["classes/Drupal/$module/"] = "$api/";
  $moves["classes/Drupal/Tests/$module/"] = "$api/Tests/";
}

// The generated top-level pages say so, and only those are replaced or
// removed, never a page someone wrote.
$generatedPages = ['hooks.md', 'events.md'];
$generatedMarker = '<!-- Generated by fix-api-docs.php: changes are lost on the next run. -->';
foreach ($generatedPages as $page) {
  if (is_file("$root/$page")) {
    if (!str_contains(file_get_contents("$root/$page"), $generatedMarker)) {
      fwrite(STDERR, "$root/$page wasn't generated by fix-api-docs.php: rename it, so the generated $page can take its place.\n");
      exit(1);
    }
    unlink("$root/$page");
  }
}

/**
 * Resolves "." and ".." in a relative path.
 */
function normalize_path(string $path): string {
  $parts = [];
  foreach (explode('/', $path) as $part) {
    if ($part === '..') {
      array_pop($parts);
    }
    elseif ($part !== '.' && $part !== '') {
      $parts[] = $part;
    }
  }
  return implode('/', $parts);
}

/**
 * Gets the path to a file relative to another file's directory.
 */
function relative_path(string $from, string $to): string {
  $fromParts = explode('/', $from);
  array_pop($fromParts);
  $toParts = explode('/', $to);
  while ($fromParts && count($toParts) > 1 && $fromParts[0] === $toParts[0]) {
    array_shift($fromParts);
    array_shift($toParts);
  }
  return './' . str_repeat('../', count($fromParts)) . implode('/', $toParts);
}

/**
 * Gets the Markdown for each constant's docblock in a PHP file, by name.
 *
 * The template doesn't output constants' docblocks, so read the source:
 * the description, and each @see as a list item.
 */
function constant_docs(string $file): array {
  $docs = [];
  $doc = '';
  $tokens = is_file($file) ? token_get_all(file_get_contents($file)) : [];
  foreach ($tokens as $i => $token) {
    if (is_array($token) && $token[0] === T_DOC_COMMENT) {
      $doc = $token[1];
    }
    elseif (is_array($token) && $token[0] === T_CONST) {
      // The name is the last identifier before "=", after any type.
      for ($j = $i + 1; $tokens[$j] !== '='; $j++) {
        if (is_array($tokens[$j]) && $tokens[$j][0] === T_STRING) {
          $name = $tokens[$j][1];
        }
      }
      $lines = preg_replace('#^\s*(/\*\*|\*/|\*) ?#', '', explode("\n", $doc));
      $description = trim(implode("\n", array_filter($lines, static fn (string $line): bool => !str_starts_with($line, '@'))));
      $sees = preg_filter('#^@see\s+(\S+).*#', '- See `$1`', $lines);
      $docs[$name] = trim($description . "\n\n" . implode("\n", $sees));
      $doc = '';
    }
    elseif ($token === ';' || $token === '}') {
      $doc = '';
    }
  }
  return $docs;
}

// Map each generated page to its new path, relative to $root. Hooks, the
// functions in *.api.php files, all go to hooks.md, each with an anchor.
// Classes of event names, with only constants, go to events.md.
$newPaths = [];
$anchors = [];
$eventClasses = [];
$files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
foreach ($files as $file) {
  if ($file->getExtension() === 'md') {
    $path = substr($file->getPathname(), strlen($dir) + 1);
    $markdown = file_get_contents($file->getPathname());
    $newPaths[$path] = "$api/$path";
    if (str_starts_with($path, 'functions/') && preg_match('/^\* Defined in: `[^`]*\.api\.php`/m', $markdown)) {
      $newPaths[$path] = 'hooks.md';
      // MkDocs' heading IDs: hook_foo_BAR_alter() becomes hook_foo_bar_alter.
      $anchors[$path] = strtolower($file->getBasename('.md'));
      continue;
    }
    if (str_starts_with($path, 'classes/') && preg_match('/^\w*Events$/', $file->getBasename('.md')) && str_contains($markdown, "\n## Constants\n") && !str_contains($markdown, "\n## Methods\n")) {
      $newPaths[$path] = 'events.md';
      $eventClasses[$path] = TRUE;
      continue;
    }
    foreach ($moves as $prefix => $replacement) {
      if (str_starts_with($path, $prefix)) {
        $newPaths[$path] = $replacement . substr($path, strlen($prefix));
        break;
      }
    }
  }
}

// Rewrite the links, then write each page to its new path.
$pages = [];
$hooks = [];
$events = [];
foreach ($newPaths as $path => $newPath) {
  $markdown = preg_replace_callback('/\[([^\]]*)\]\(([^)#:]+)\)/', static function (array $match) use ($path, $newPath, $newPaths, $anchors): string {
    [, $text, $target] = $match;
    $target = normalize_path(dirname($path) . '/' . preg_replace('/\.md$/', '', $target)) . '.md';
    $anchor = isset($anchors[$target]) ? '#' . $anchors[$target] : '';
    return isset($newPaths[$target]) ? "[$text](" . relative_path($newPath, $newPaths[$target]) . "$anchor)" : $text;
  }, file_get_contents("$dir/$path"));
  unlink("$dir/$path");
  if (isset($anchors[$path])) {
    // A section of hooks.md: its headings move down a level.
    $hooks[$path] = '## ' . basename($path, '.md') . "()\n" . preg_replace('/^(#+) /m', '#$1 ', $markdown);
    continue;
  }
  if (isset($eventClasses[$path])) {
    // A section of events.md for each constant, headed by the event name,
    // with the constant's docblock from the class's file: src/ for
    // \Drupal\<module>\..., or tests/src/ for \Drupal\Tests\<module>\....
    preg_match('/^\* Full name: `\\\\?([^`]+)`/m', $markdown, $match);
    $class = $match[1];
    $source = preg_replace(["#^Drupal/Tests/$module/#", "#^Drupal/$module/#"], ['tests/src/', 'src/'], str_replace('\\', '/', $class)) . '.php';
    $docs = constant_docs($source);
    preg_match_all('/^\| `(\w+)` +\|[^|]*\|[^|]*\| \'([^\']*)\' +\|$/m', $markdown, $constants, PREG_SET_ORDER);
    foreach ($constants as [, $name, $value]) {
      $events[$path][] = "## $value\n\n" . (empty($docs[$name]) ? '' : "$docs[$name]\n\n") . "* Constant: `\\$class::$name`\n";
    }
    continue;
  }
  $pages[$newPath] = $markdown;
}
if ($events) {
  ksort($events);
  $pages['events.md'] = "# Events\n\n$generatedMarker\n\n" . implode("\n***\n\n", array_merge(...array_values($events)));
}
if ($hooks) {
  // In the order of the generated index, which follows the source files.
  $index = $pages["$api/index.md"];
  uksort($hooks, static fn (string $a, string $b): int => strpos($index, "#$anchors[$a])") <=> strpos($index, "#$anchors[$b])"));
  $pages['hooks.md'] = "# Hooks\n\n$generatedMarker\n\n" . implode("\n***\n\n", $hooks);
  if (!preg_grep('#^' . preg_quote("$api/functions/", '#') . '#', $newPaths)) {
    $pages["$api/index.md"] = str_replace("#### Functions\n\n| Function ", "#### Hooks\n\n| Hook ", $index);
  }
}
foreach ($pages as $newPath => $markdown) {
  // Without a heading, MkDocs titles a page from its file name, such as
  // "Index", or "Hook foo alter" for hook_foo_alter(), so add one: the class
  // or function name from the page's "Full name" line.
  if (!str_starts_with(ltrim($markdown), '# ')) {
    if ($newPath === "$api/index.md") {
      $markdown = "# API reference\n\n" . $markdown;
    }
    elseif (preg_match('/^\* Full name: `\\\\?(?:[^`]*\\\\)?([^`\\\\]+)`/m', $markdown, $match)) {
      $markdown = '# ' . $match[1] . (str_starts_with($newPath, "$api/functions/") ? '()' : '') . "\n" . $markdown;
    }
  }
  if (!is_dir(dirname("$root/$newPath"))) {
    mkdir(dirname("$root/$newPath"), 0777, TRUE);
  }
  file_put_contents("$root/$newPath", $markdown);
}

// Remove the directories left empty.
$directories = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
foreach ($directories as $directory) {
  if ($directory->isDir() && !(new FilesystemIterator($directory->getPathname()))->valid()) {
    rmdir($directory->getPathname());
  }
}
